#!/usr/bin/env bash
# Builds the unsigned, aligned APK from a project generated by generate-project.cjs.
# It needs no secrets: Gradle downloads plugins from the network, so signing is a
# separate step (sign-apk.sh) that never runs alongside it.
# Usage: deploy/android/build-apk.sh <project-dir> <unsigned.apk>
# Needs: JDK 17+ on PATH or JAVA_HOME, ANDROID_HOME with build-tools 36.1.0.
set -euo pipefail

PROJECT="${1:?project directory}"
OUTPUT="${2:?output apk path}"
BUILD_TOOLS="${ANDROID_HOME:?ANDROID_HOME is not set}/build-tools/36.1.0"

(cd "$PROJECT" && chmod +x gradlew && ./gradlew --no-daemon --quiet assembleRelease)
"$BUILD_TOOLS/zipalign" -p -f 4 "$PROJECT/app/build/outputs/apk/release/app-release-unsigned.apk" "$OUTPUT"
